<template><div><div class="page-heading"><div><div class="eyebrow-label">ACCOUNT CENTER</div><h1>个人中心</h1><p>管理你的平台身份、联系信息和登录安全</p></div><el-button plain @click="logout">退出当前账号</el-button></div><div class="grid profile-grid"><div class="panel profile-identity"><div class="profile-avatar">{{initials}}</div><h2>{{form.displayName||form.username}}</h2><p class="muted">@{{form.username}}</p><el-tag type="success" effect="dark">{{form.role||'USER'}} · ACTIVE</el-tag><div class="profile-meta"><div><span>注册邮箱</span><b>{{form.email}}</b></div><div><span>加入时间</span><b>{{formatDate(form.createdAt)}}</b></div></div></div><div class="panel"><div class="panel-title"><b>基本资料</b><span class="muted">PROFILE INFORMATION</span></div><el-form :model="form" label-position="top"><el-form-item label="显示名称"><el-input v-model="form.displayName"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.phone" placeholder="未填写"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" disabled/></el-form-item><el-button type="primary" :loading="saving" @click="saveProfile">保存资料</el-button></el-form></div><div class="panel"><div class="panel-title"><b>修改密码</b><span class="muted">SECURITY</span></div><el-form :model="password" label-position="top"><el-form-item label="原密码"><el-input v-model="password.oldPassword" type="password" show-password/></el-form-item><el-form-item label="新密码"><el-input v-model="password.newPassword" type="password" show-password/></el-form-item><el-button type="primary" plain @click="changePassword">更新密码</el-button></el-form></div></div></div></template>
<script setup>import{ref,onMounted,computed}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{authApi}from'../api/http';const router=useRouter(),form=ref({}),password=ref({oldPassword:'',newPassword:''}),saving=ref(false),initials=computed(()=>(form.value.displayName||form.value.username||'GU').slice(0,2).toUpperCase());onMounted(async()=>{try{form.value=(await authApi.me()).user}catch{router.push('/login')}});function formatDate(v){return v?String(v).slice(0,10):'—'}async function saveProfile(){saving.value=true;try{form.value=(await authApi.updateProfile({displayName:form.value.displayName,phone:form.value.phone})).user;ElMessage.success('资料已保存')}catch(e){ElMessage.error(e.response?.data?.message||'保存失败')}finally{saving.value=false}}async function changePassword(){if(!password.value.oldPassword||!password.value.newPassword)return ElMessage.warning('请填写完整密码');try{await authApi.changePassword(password.value);password.value={oldPassword:'',newPassword:''};ElMessage.success('密码修改成功')}catch(e){ElMessage.error(e.response?.data?.message||'密码修改失败')}}async function logout(){await authApi.logout();router.push('/login')}</script>
